function pairForTarget(nums: number[], target: number): number[] {
  const idx = nums.map((_, i) => i).sort((a, b) => nums[a] - nums[b]);
  let lo = 0, hi = idx.length - 1;
  while (lo < hi) {
    const sum = nums[idx[lo]] + nums[idx[hi]];
    if (sum === target) return [Math.min(idx[lo], idx[hi]), Math.max(idx[lo], idx[hi])];
    if (sum < target) lo++;
    else hi--;
  }
  return [];
}

